using CoHost.Contracts;
using Xunit;

namespace CoHost.Protocol.Tests;

/// <summary>
/// Released v0.1 wire samples must keep parsing with the current code (SPEC 2.3).
/// The sample files are frozen artifacts and are never regenerated by tests.
/// </summary>
public sealed class CompatTests
{
    private static string SampleDir => Path.Combine(AppContext.BaseDirectory, "compat", "v0.1");

    public static TheoryData<string> Files()
    {
        var data = new TheoryData<string>();
        foreach (var file in Directory.GetFiles(SampleDir, "*.json").Order())
        {
            data.Add(Path.GetFileName(file));
        }

        return data;
    }

    [Fact]
    public void Every_discriminator_has_a_sample()
    {
        var missing = new List<string>();
        foreach (var (channel, baseType) in new[]
        {
            ("agent", typeof(AgentMessage)), ("client", typeof(ClientMessage)), ("admin", typeof(AdminMessage)),
        })
        {
            foreach (var d in Discriminators.Map(baseType).Values)
            {
                if (!File.Exists(Path.Combine(SampleDir, $"{channel}.{d}.json"))) missing.Add($"{channel}.{d}.json");
            }
        }

        Assert.Empty(missing);
        Assert.Equal(19, Directory.GetFiles(SampleDir, "*.json").Length);
    }

    [Theory]
    [MemberData(nameof(Files))]
    public void Released_samples_still_parse(string fileName)
    {
        var stem = Path.GetFileNameWithoutExtension(fileName);
        var dot = stem.IndexOf('.');
        var channel = stem[..dot];
        var discriminator = stem[(dot + 1)..];

        var (message, unknown) = Discriminators.Parse(channel, File.ReadAllBytes(Path.Combine(SampleDir, fileName)));

        Assert.Null(unknown);
        Assert.NotNull(message);
        Assert.Equal(discriminator, Discriminators.Of(message));
    }
}
